    /** @param array<int,string> $names */
    private function catId(array $names): ?int
    {
        foreach ($names as $name) {
            try {
                $cat = Category::whereRaw("JSON_UNQUOTE(JSON_EXTRACT(name, '$.fr_CA')) = ?", [$name])->first();
                if ($cat) {
                    return $cat->id;
                }
            } catch (\Throwable $e) { /* silent */ }
        }

        return null;
    }
